import { migrate } from "drizzle-orm/node-postgres/migrator";
import { ownerDb, ownerPool } from "./owner";

// Applies the SQL files generated by `pnpm db:generate`, as the owner of the tables (the API's own
// user cannot change the structure). Safe to run repeatedly.
const migrationsFolder = new URL("../../drizzle", import.meta.url).pathname;

await migrate(ownerDb, { migrationsFolder });
await ownerPool.end();
console.log("Migrations applied.");
